import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String placa = br.readLine();

        if (isOldPattern(placa)) {
            System.out.println(1);
        } else if (isMercosulPattern(placa)) {
            System.out.println(2);
        } else {
            System.out.println(0);
        }
    }

    static boolean isOldPattern(String s) {
        if (s.length() != 8) return false;

        for (int i = 0; i < 3; i++) {
            if (!isUpper(s.charAt(i))) return false;
        }

        if (s.charAt(3) != '-') return false;

        for (int i = 4; i < 8; i++) {
            if (!isDigit(s.charAt(i))) return false;
        }

        return true;
    }

    static boolean isMercosulPattern(String s) {
        if (s.length() != 7) return false;

        for (int i = 0; i < 3; i++) {
            if (!isUpper(s.charAt(i))) return false;
        }

        if (!isDigit(s.charAt(3))) return false;
        if (!isUpper(s.charAt(4))) return false;

        for (int i = 5; i < 7; i++) {
            if (!isDigit(s.charAt(i))) return false;
        }

        return true;
    }

    static boolean isUpper(char c) {
        return c >= 'A' && c <= 'Z';
    }

    static boolean isDigit(char c) {
        return c >= '0' && c <= '9';
    }
}
